const obj = {
  name: "Alice",
  details: {
    age: 25,
    city: "Wonderland",
  },
};

// Freeze only the "details" key
Object.defineProperty(obj, "details", {
  writable: false,    // Prevents reassignment of the "details" key
  configurable: false // Prevents deletion or redefinition
});

// Attempt to reassign "details"
obj.details = {}; // This will not work

// To freeze the nested "details" object
Object.freeze(obj.details);

// Attempt to modify the nested "details" object
obj.details.city = "Dreamland"; // This will not work
console.log(obj.details.city); 
// Output: Wonderland
